package ibm.jceplus.junit.tests;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.params.provider.MethodSource;

/**
 * Runs the XDH KeyAgreement interop tests between the OCK and OpenSSL backends
 * of the same OpenJCEPlus provider, so that keys generated by one backend are
 * used by a KeyAgreement running on the other backend, in both directions.
 *
 * <p>OpenSSL is not available on z/OS; the factory method returns an empty stream there,
 * so no test cases will be generated on that platform.
 */
@Tag(Tags.OPENJCEPLUS_OCK_NAME)
@Tag(Tags.OPENJCEPLUS_OPENSSL_NAME)
@MethodSource("ibm.jceplus.junit.tests.TestArguments#getOCKAndOpenSSLCrossBackendProviders")
public class TestXDHKeyAgreementInteropBackends extends TestXDHKeyAgreementInterop {
    // Parameter injection and all test methods are inherited from TestXDHKeyAgreementInterop.
}
